        raise ValueError("Username must be a non-empty string.")
    response = requests.get(URL + username)
    response.raise_for_status()
    data = response.json()
    normalized_data = {}
    for key, value in data.items():
        if isinstance(value, str):
            normalized_value = unicodedata.normalize('NFKD', value).encode('ascii', 'ignore').decode('ascii')
            normalized_data[key] = normalized_value
        else:
            normalized_data[key] = value
    return normalized_data

from flask import Flask
from flask_restful import Resource, Api
import requests
def task_func(api_url, template_folder):
    app = Flask(__name__, template_folder=template_folder)
    api = Api(app)

    class ExternalAPI(Resource):
        def get(self):
            try:
                response = requests.get(api_url)
                response.raise_for_status()
                return response.json()
            except requests.RequestException as e:
                return {"error": str(e)}, 500

    api.add_resource(ExternalAPI, '/api/data')

    return app

